def send_telegram(msg):
    try:
        requests.post(f'https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage',
            json={'chat_id': TELEGRAM_CHAT_ID, 'text': msg, 'parse_mode': 'HTML'}, timeout=10)
    except: pass

def run_ffmpeg(cmd, label=''):
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode != 0: print(f'FFmpeg [{label}] error: {r.stderr[-200:]}')
    else:
        if label: print(f'FFmpeg [{label}] OK')
    return r.returncode == 0

def get_youtube():
    creds = pickle.loads(base64.b64decode(os.environ['TOKEN_PICKLE_B64']))
    if creds.expired and creds.refresh_token: creds.refresh(Request())
    return build('youtube', 'v3', credentials=creds)

def buscar_playlist(yt, nombre):
    try:
        r = yt.playlists().list(part='snippet', mine=True, maxResults=50).execute()
        for item in r.get('items', []):
            if nombre.lower() in item['snippet']['title'].lower():
                return item['id']
    except: pass
    return None

def obtener_playlist(yt, nombre, desc, idioma='es'):
    pid = buscar_playlist(yt, nombre)
    if pid: return pid
    try:
        pl = yt.playlists().insert(part='snippet,status', body={
            'snippet': {'title': nombre, 'description': desc, 'defaultLanguage': idioma},
            'status': {'privacyStatus': 'public'}
        }).execute()
        return pl['id']
    except: return None

def agregar_playlist(yt, vid, pid):
    if not pid: return
    try:
        yt.playlistItems().insert(part='snippet', body={
            'snippet': {'playlistId': pid, 'resourceId': {'kind': 'youtube#video', 'videoId': vid}}
        }).execute()
    except: pass

def dia_serie():
    try: return min(int(open('serie_dia.txt').read().strip()), len(SERIE_30_DIAS))
    except: return 1

def avanzar_serie():
    d = dia_serie()
    open('serie_dia.txt','w').write(str((d % len(SERIE_30_DIAS)) + 1))
    return d

def fecha_especial():
    hoy = datetime.now()
    if hoy.day==10 and hoy.month==10: return 'dia mundial salud mental por que es tan importante hoy'
    if hoy.day==10 and hoy.month==9: return 'prevencion del suicidio lo que todos debemos saber'
    if hoy.weekday()==0: return 'como empezar la semana cuidando tu salud mental'
    return None

def descargar_pexels(queries, orientacion, n=5):
    os.makedirs('/tmp/px', exist_ok=True)
    videos = []
    headers = {'Authorization': PEXELS_API_KEY}
    for _ in range(3):
        if len(videos) >= n: break
        try:
            r = requests.get('https://api.pexels.com/videos/search', headers=headers,
                params={'query': random.choice(queries), 'orientation': orientacion, 'per_page': 15, 'size': 'medium'}, timeout=30)
            items = r.json().get('videos', [])
            random.shuffle(items)
            for item in items:
                if len(videos) >= n: break
                try:
                    files = sorted([f for f in item.get('video_files',[]) if f.get('width',0)>=640], key=lambda x: x.get('width',0))
                    if not files: continue
                    raw = f'/tmp/px/r_{orientacion}_{len(videos)}.mp4'
                    vr = requests.get(files[0]['link'], timeout=60, stream=True)
                    with open(raw,'wb') as f:
                        for chunk in vr.iter_content(1024*1024): f.write(chunk)
                    if not os.path.exists(raw) or os.path.getsize(raw) < 100000: continue
                    proc = f'/tmp/px/p_{orientacion}_{len(videos)}.mp4'
                    vf = 'scale=1280:720:force_original_aspect_ratio=decrease,pad=1280:720:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1' if orientacion=='landscape' else 'scale=608:1080:force_original_aspect_ratio=decrease,pad=608:1080:(ow-iw)/2:(oh-ih)/2:color=black,setsar=1'
                    if run_ffmpeg(['ffmpeg','-y','-i',raw,'-vf',vf,'-t','15','-c:v','libx264','-pix_fmt','yuv420p','-r','25','-an',proc], f'px_{len(videos)}'):
                        if os.path.exists(proc) and os.path.getsize(proc) > 50000:
                            videos.append(proc)
                except: pass
        except: pass
    if len(videos) < 2:
        carpeta = 'assets/videos_h_small' if orientacion=='landscape' else 'assets/videos_v_small'
        if os.path.exists(carpeta):
            local = [os.path.join(carpeta,f) for f in os.listdir(carpeta) if f.endswith('.mp4')]
            random.shuffle(local)
            videos.extend(local[:n])
    print(f'Pexels {orientacion}: {len(videos)} videos')
    return videos

def extraer_json(texto):
    # Remover thinking tokens
    texto = re.sub(r'<think[^>]*>[\s\S]*?</thinking>', '', texto).strip()
    # Buscar por posicion de llaves
    start = texto.find('{')
    end = texto.rfind('}')
    if start != -1 and end != -1 and end > start:
        try:
            return json.loads(texto[start:end+1], strict=False)
        except Exception as e:
            print(f'JSON parse error: {e}')
    print(f'No JSON en: {texto[:200]}')
    return None

def generar_guion(tema, idioma='es'):
    client = Groq(api_key=GROQ_API_KEY)
    if idioma == 'es':
        instruccion = 'Eres psicologo para YouTube en espaÃƒÂ±ol latino. Crea contenido sobre el tema dado. Responde UNICAMENTE con un objeto JSON valido con estos campos: titulo (string con 2 emojis al inicio, maximo 60 caracteres, viral), descripcion (string 300 palabras con emojis y hashtags), guion (string 400 palabras texto limpio sin emojis para narrar en voz), guion_short (string 60 palabras texto limpio sin emojis), titulo_short (string 2 emojis inicio maximo 40 caracteres), tags (array de 10 strings), comentario_ancla (string 1 frase empatica).'
    else:
        instruccion = 'You are a psychologist for YouTube. Create content about the given topic. Respond ONLY with a valid JSON object with these fields: titulo (string 2 emojis start max 60 chars viral), descripcion (string 200 words emojis hashtags), guion (string 350 words clean text no emojis for narration), guion_short (string 50 words clean text no emojis), titulo_short (string 2 emojis start max 40 chars), tags (array 10 strings), comentario_ancla (string 1 empathetic phrase).'
    for intento in range(3):
        try:
            import time
            if intento > 0: time.sleep(20)
            resp = client.chat.completions.create(
                model='groq/compound-mini',
                messages=[{'role':'system','content':instruccion},{'role':'user','content':f'Tema: {tema}'}],
                max_tokens=2000,
                temperature=0.8
            )
            content = resp.choices[0].message.content or ''
            if '<think' in content:
                idx = content.rfind('>')
                if idx != -1:
                    content = content[idx+1:].strip()
            start = content.find('{')
            end = content.rfind('}')
            if start != -1 and end != -1 and end > start:
                try:
                    datos = json.loads(content[start:end+1], strict=False)
                    guion = datos.get('guion', '')
                    if datos and 'titulo' in datos and guion and len(guion.split()) > 30:
                        print(f'Guion {idioma}: {len(guion.split())} palabras OK')
                        return datos
                    print(f'JSON incompleto: titulo={bool(datos.get("titulo"))} guion_palabras={len(guion.split())}')
                except Exception as je:
                    print(f'JSON parse error: {je}')
            print(f'Reintentando {intento+1}/3 - respuesta: {content[:100]}')
        except Exception as e:
            print(f'Error Groq {intento+1}: {e}')
    raise ValueError(f'No se pudo generar guion: {tema}')

async def tts(texto, audio, srt, voz):
    import edge_tts
    rate = random.choice(['-8%','-10%','-12%'])
    pitch = random.choice(['-3Hz','-4Hz','-5Hz'])
    texto_limpio = limpiar_texto(texto)
    print(f'TTS: {len(texto_limpio.split())} palabras rate={rate}')
    comm = edge_tts.Communicate(texto_limpio, voz, rate=rate, pitch=pitch, volume=VOZ_VOLUME)
    words, audio_data = [], b''
    async for chunk in comm.stream():
        if chunk['type'] == 'audio': audio_data += chunk['data']
        elif chunk['type'] == 'WordBoundary':
            words.append({'w': chunk['text'], 's': chunk['offset']/1e7, 'e': (chunk['offset']+chunk['duration'])/1e7})
    open(audio,'wb').write(audio_data)
    print(f'Audio: {len(audio_data)} bytes ~{len(audio_data)/16000:.0f}s')
    if words:
        def fmt(s):
            return f'{int(s//3600):02d}:{int((s%3600)//60):02d}:{int(s%60):02d},{int((s%1)*1000):03d}'
        grupos, g = [], []
        for w in words:
            g.append(w)
            if len(g) >= 5: grupos.append(g); g = []
        if g: grupos.append(g)
        with open(srt,'w',encoding='utf-8') as f:
            for i,gr in enumerate(grupos):
                f.write(f"{i+1}\n{fmt(gr[0]['s'])} --> {fmt(gr[-1]['e'])}\n{' '.join(x['w'] for x in gr)}\n\n")
        print(f'SRT: {len(grupos)} grupos')

def duracion_audio(f):
    r = subprocess.run(['ffprobe','-v','quiet','-print_format','json','-show_format',f], capture_output=True, text=True)
    try:
        d = float(json.loads(r.stdout)['format']['duration'])
        print(f'Duracion {os.path.basename(f)}: {d:.1f}s')
        return d
    except: return 0.0

def get_musica():
    c = 'assets/music_small'
    if not os.path.exists(c): return None
    files = [os.path.join(c,f) for f in os.listdir(c) if f.endswith('.mp3')]
    return random.choice(files) if files else None

def mezclar(voz, musica, salida, vol=0.08):
    import shutil
    dur = duracion_audio(voz)
    if dur < 20:
        print(f'Audio muy corto ({dur:.1f}s) - usando solo voz')
        shutil.copy(voz, salida)
        return
    ok = run_ffmpeg(['ffmpeg','-y','-i',voz,'-i',musica,
        '-filter_complex',f'[0:a]aformat=sample_rates=44100:channel_layouts=stereo[a1];[1:a]volume={vol},aformat=sample_rates=44100:channel_layouts=stereo,aloop=loop=-1:size=2e+09[a2];[a1][a2]amix=inputs=2:duration=first:dropout_transition=3[out]',
        '-map','[out]','-c:a','aac','-b:a','128k','-ar','44100',salida], 'mezcla')
    if not ok or not os.path.exists(salida) or os.path.getsize(salida)<1000:
        shutil.copy(voz, salida)
        print('Mezcla fallida - solo voz')

